import ast
import operator

def eval_expression(expr):
    """
    Computes the mathematical expression `expr`, respecting the order of operations 
    and handling negative numbers. Raises ZeroDivisionError when dividing by zero.
    """
    # Supported operators mapping for the AST evaluator
    operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    def _eval(node):
        if isinstance(node, ast.Constant):  # Number literals (Python 3.8+)
            if isinstance(node.value, (int, float)):
                return node.value
            raise TypeError(f"Unsupported constant type: {type(node.value)}")

        elif isinstance(node, ast.BinOp):  # Binary operations (e.g., a + b)
            if type(node.op) in operators:
                left = _eval(node.left)
                right = _eval(node.right)
                try:
                    return operators[type(node.op)](left, right)
                except ZeroDivisionError:
                    raise ZeroDivisionError("division by zero")
            else:
                raise TypeError(f"Unsupported operator: {type(node.op)}")

        elif isinstance(node, ast.UnaryOp):  # Unary operations (e.g., -5)
            if type(node.op) in operators:
                operand = _eval(node.operand)
                return operators[type(node.op)](operand)
            else:
                raise TypeError(f"Unsupported unary operator: {type(node.op)}")

        elif isinstance(node, ast.Expression):  # Root node
            return _eval(node.body)

        else:
            raise TypeError(f"Unsupported expression structure: {type(node)}")

    # Parse the expression into an Abstract Syntax Tree (AST)
    try:
        tree = ast.parse(expr.strip(), mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid expression syntax: {expr}") from e

    return _eval(tree)

# --- Examples ---
if __name__ == "__main__":
    print(eval_expression('"3 + 4 * (2 - 1)"'))  # Output: 7
    print(eval_expression("-5 + 10 * (-2)"))       # Output: -25

    try:
        eval_expression("5 / 0")
    except ZeroDivisionError:
        print("Caught division by zero!")          # Output: Caught division by zero!
